pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address depositor1, address depositor2, uint256 amount1, uint256 amount2) public {
        vm.assume(depositor1 != address(0) && depositor2 != address(0));
        vm.assume(depositor1 != depositor2);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 <= type(uint256).max / 2 && amount2 <= type(uint256).max / 2);

        // initialize
        c.Initialized();
        c.SetMinSum(0);

        // fund depositors
        vm.deal(depositor1, amount1);
        vm.deal(depositor2, amount2);

        vm.prank(depositor1);
        c.Deposit{value: amount1}();

        vm.prank(depositor2);
        c.Deposit{value: amount2}();

        // general rule: sum of balances of the two depositors equals sum of their deposits
        uint256 sumBalances = c.balances(depositor1) + c.balances(depositor2);
        uint256 sumDeposits = amount1 + amount2;
        assertTrue(sumBalances == sumDeposits);
    }
}

