pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount0, uint256 amount1) public {
        // Restrict amounts to avoid reverts from overflow in the reference contract's require,
        // but keep the domain wide enough that the fuzzer can find values that overflow without it.
        vm.assume(uint256(type(uint128).max) - amount0 >= amount1);

        address actor = address(0x1000);
        vm.deal(actor, 1000 ether);

        vm.startPrank(actor);
        c.Deposit{value: amount0}();
        c.Deposit{value: amount1}();
        vm.stopPrank();

        // Total ether deposited by this actor
        uint256 totalDeposited = amount0 + amount1;
        // The actor's balance according to c
        uint256 actorBalance = c.balances(actor);

        // General invariant: a single user's balance must never exceed total deposits.
        // The reference satisfies this for all inputs, but the buggy version can have balance < totalDeposited
        // due to overflow (balance wraps around while totalDeposited does not).
        // Actually, the more precise invariant: balance must equal total deposited if no collects.
        // But overflow makes balance < totalDeposited. We assert balance >= totalDeposited is impossible.
        // Let's assert that the balance is NOT less than the sum of its own deposits.
        // Wait, overflow would make balance smaller, so balance < totalDeposited.
        // So we assert balance >= totalDeposited. Reference: always true (no overflow, and require prevents overflow).
        // Bug: can overflow causing balance < totalDeposited, violation.
        assertTrue(actorBalance >= totalDeposited);
    }
}

