pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 deposit3) public {
        // Keep deposits in admissible range (not too large to allow fuzzer to explore overflow)
        deposit1 = bound(deposit1, 0, type(uint128).max);
        deposit2 = bound(deposit2, 0, type(uint128).max);
        deposit3 = bound(deposit3, 0, type(uint128).max);

        address user1 = address(0x100);
        address user2 = address(0x200);
        address user3 = address(0x300);

        // Fund users
        vm.deal(user1, deposit1);
        vm.deal(user2, deposit2);
        vm.deal(user3, deposit3);

        // Perform deposits
        vm.prank(user1);
        c.Deposit{value: deposit1}();

        vm.prank(user2);
        c.Deposit{value: deposit2}();

        vm.prank(user3);
        c.Deposit{value: deposit3}();

        // The invariant: sum of all balances must equal total ETH in contract + any collected funds (none here)
        uint256 sumBalances = c.balances(user1) + c.balances(user2) + c.balances(user3);
        uint256 totalDeposited = deposit1 + deposit2 + deposit3;
        // In correct contract, sumBalances == totalDeposited (and equals address(c).balance since no collects)
        // Buggy version may have sumBalances < totalDeposited due to overflow on any single deposit
        assertTrue(sumBalances == totalDeposited);
    }
}

